<section class="vc-page-actions"><div><span class="vc-status info" id="ve-status">Loading events…</span></div><a class="vc-btn" href="../../../events.html" target="_blank" rel="noopener">Public event page <i class="fa-solid fa-arrow-up-right-from-square"></i></a></section>
<section class="vc-card"><div class="vc-card-head"><h2>Upcoming events</h2><span class="vc-help">Apply directly to events accepting vendor applications.</span></div><div class="vc-card-body"><div class="vc-grid three" id="ve-upcoming"></div></div></section>
<section class="vc-card mt-3"><div class="vc-card-head"><h2>My applications</h2></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Event</th><th>Submitted</th><th>Status</th><th>Fee</th><th>Payment</th></tr></thead><tbody id="ve-applications"><tr><td colspan="5">Loading…</td></tr></tbody></table></div></section>
<dialog class="vc-dialog" id="ve-dialog"><div class="vc-dialog-head"><h2 id="ve-title">Apply to event</h2><button type="button" class="vc-btn small" id="ve-close">Close</button></div><form class="vc-dialog-body" id="ve-form"><input type="hidden" name="event_id"><div class="vc-field"><label>What will you exhibit or demonstrate?</label><textarea class="vc-textarea" name="application_text" minlength="40" maxlength="3000" required rows="6" placeholder="Describe your products, materials, maker story, and what visitors can experience."></textarea></div><div class="vc-field"><label>Stall, power, or accessibility requirements</label><textarea class="vc-textarea" name="stall_requirements" maxlength="1000" rows="3" placeholder="Optional"></textarea></div><p class="vc-help">Submitting an application does not confirm your place. The event team will review it and show any fee or payment step in your application status.</p><div class="vc-form-actions"><button type="submit" class="vc-btn primary">Submit application</button></div></form></dialog>
